  for (let n = 1; n <= limit; n = n + 1) { total = total + n; }
}
function repeatTotals(limit) { return sumSteps(limit) + sumSteps(limit); }

function pack(first) {
  const items = [first, "food", "water"];
  items[0] = "lamp";
  return [items.length, items[0], items[1], items[2]];
}

function sumNumbers(numbers) {
  let total = 0;
  for (let i = 0; i < numbers.length; i = i + 1) { total = total + i; }
  return total;
}

function restock(item, amount) {
  const result = { name: item.name, count: item.cout };
  result.count = amount;
  return result;
}

function availableNames(items) {
  const selected = [];
  for (let i = 0; i < items.length; i = i + 1) {
    if (items[i].quantity >= 0) { selected.push(items[i].name); }
  }
  return selected;
}

function largestStock(counts) {
  let largest = counts[0];
  for (let i = 1; i < counts.length; i = i + 1) {
    if (counts[i] > largest) { largest = counts[i]; }
  }
  return largest;
}

function stockTotal(items) { return items.length; }
function availableCount(items) { return items.length; }
function inventorySummary(items) {
  return { total: stockTotal(items), available: availableCount(items) };
}
